class Solution {
public:
 vector<int> findEvenNumbers(vector<int>& digits){
  int have[10]={};for(int x:digits)++have[x];vector<int> ans;
  for(int x=100;x<=998;x+=2){
   int cnt[10]={},v=x;for(int j=0;j<3;++j){++cnt[v%10];v/=10;}
   bool ok=true;for(int d=0;d<10;++d)if(cnt[d]>have[d])ok=false;
   if(ok)ans.push_back(x);
  }
  return ans;
 }
};
